<?php
declare(strict_types=1);
function s24_h(string $value):string{return htmlspecialchars($value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function s24_origin():string{$https=isset($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!==''&&strtolower((string)$_SERVER['HTTPS'])!=='off';$scheme=$https?'https':'http';$host=(string)($_SERVER['HTTP_HOST']??'localhost');$host=preg_replace('/[^A-Za-z0-9.\-:\[\]]/','',$host)?:'localhost';return $scheme.'://'.$host;}
function s24_shop_path():string{$script=str_replace('\\','/',(string)($_SERVER['SCRIPT_NAME']??'/shop/index.php'));$dir=rtrim(str_replace('\\','/',dirname($script)),'/');return $dir===''||$dir==='.'?'/shop':$dir;}
function s24_url(string $relative=''):string{return s24_origin().s24_shop_path().'/'.ltrim($relative,'/');}
function s24_asset(string $file):string{$path=__DIR__.'/'.ltrim($file,'/');$version=is_file($path)?(string)filemtime($path):'24';return ltrim($file,'/').'?v='.rawurlencode($version);}
function s24_head(string $title,string $description,string $canonical='index.php',string $robots='index,follow,max-image-preview:large',?array $jsonLd=null):void{$canonicalUrl=s24_url($canonical);$logoUrl=s24_origin().rtrim(dirname(s24_shop_path()),'/').'/img/logo.png';$safeTitle=s24_h($title);$safeDescription=s24_h($description);$safeCanonical=s24_h($canonicalUrl);$safeLogo=s24_h($logoUrl);$safeRobots=s24_h($robots);echo '<meta charset="utf-8">';echo '<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">';echo '<meta name="description" content="'.$safeDescription.'">';echo '<meta name="robots" content="'.$safeRobots.'">';echo '<meta name="theme-color" content="#247443">';echo '<meta name="color-scheme" content="light">';echo '<meta name="application-name" content="Healthcare Wellness Club">';echo '<meta name="apple-mobile-web-app-capable" content="yes">';echo '<meta name="apple-mobile-web-app-status-bar-style" content="default">';echo '<meta name="apple-mobile-web-app-title" content="HWC Store">';echo '<title>'.$safeTitle.'</title>';echo '<link rel="canonical" href="'.$safeCanonical.'">';echo '<link rel="manifest" href="manifest.webmanifest">';echo '<link rel="icon" href="icon-192.png" type="image/png" sizes="192x192">';echo '<link rel="apple-touch-icon" href="icon-192.png">';echo '<meta property="og:type" content="website">';echo '<meta property="og:site_name" content="Healthcare Wellness Club">';echo '<meta property="og:title" content="'.$safeTitle.'">';echo '<meta property="og:description" content="'.$safeDescription.'">';echo '<meta property="og:url" content="'.$safeCanonical.'">';echo '<meta property="og:image" content="'.$safeLogo.'">';echo '<meta name="twitter:card" content="summary">';echo '<meta name="twitter:title" content="'.$safeTitle.'">';echo '<meta name="twitter:description" content="'.$safeDescription.'">';echo '<link rel="stylesheet" href="'.s24_h(s24_asset('store.css')).'">';echo '<link rel="stylesheet" href="'.s24_h(s24_asset('premium-light.css')).'">';if($jsonLd!==null){echo '<script type="application/ld+json">';echo json_encode($jsonLd,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT);echo '</script>';}}
